package org.sleepwell.app;

import android.app.*;
import android.content.Context;
import android.os.Bundle;
import android.widget.*;
import android.view.*;
import org.json.JSONObject;
import java.util.*;
import java.util.concurrent.*;

/** Supporting measured-signal view; manual entries never receive fabricated plots. */
public final class RecordSignalsActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private RecordEntry record;private List<JSONObject> epochs=List.of(),events=List.of();private boolean original;private int generation,savedClips;private String metric="movement";private long inspection=-1;private RecordChart chart;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);original=state!=null&&state.getBoolean("original");if(state!=null){metric=state.getString("metric","movement");inspection=state.getLong("inspection",-1);}load();}
    private void load(){long id=getIntent().getLongExtra("record",0);int request=++generation;Records.Factory factory=Records.factory;Context application=getApplicationContext();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Recorded signals",this::finish);Design.text(body,"Loading signals…",15,400,Design.MUTED);
        worker.execute(()->{try(Store store=factory.open(application)){RecordEntry entry=Records.get(store,id);List<JSONObject> data=store.rows("SELECT * FROM epochs WHERE session=? ORDER BY time",""+id),analysis=store.rows("SELECT time,duration_ms FROM sound_events WHERE session=? ORDER BY time",""+id);int available=ReportSounds.read(application,store,entry).availableClips;runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;record=entry;epochs=data;events=analysis;savedClips=available;render();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;LinearLayout page=Design.page(this,false,null,n->{});RecordUi.header(page,"Recorded signals",this::finish);Design.space(page,24);Design.text(page,"Signals unavailable",22,600,Design.INK);Design.text(page,"This recording could not be opened.",15,400,Design.MUTED);Design.space(page,16);Design.button(page,"Try again",true,this::load);});}});
    }
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Night details",this::finish);Design.space(body,8);Design.text(body,record.provenance(),13,400,NightDialTokens.SECONDARY);if(record.manual()){Design.space(body,28);Design.text(body,"No sensor measurements",22,500,NightDialTokens.TEXT);Design.space(body,10);Design.text(body,"This period has no local movement, microphone or light measurements.",15,400,NightDialTokens.SECONDARY);if(record.csvImported)destination(body,"report","Original CSV signals","Values reported by the source",()->startActivity(SleepCsvSourceActivity.intent(this,record.id)));return;}
        if(record.edited){Design.space(body,12);RecordUi.segments(body,new String[]{"Edited period","Original capture"},original?1:0,index->{rememberInspection();original=index==1;render();});}
        long start=original?record.rawStart:record.edit.start,end=original?record.rawEnd:record.edit.end;List<JSONObject> visible=Records.window(epochs,start,end);Design.space(body,12);TextView period=Design.text(body,(record.sonar()?RecordUi.preciseClock(this,start,record.zone()):RecordUi.clock(this,start,record.zone()))+" – "+(record.sonar()?RecordUi.preciseClock(this,end,record.zone()):RecordUi.clock(this,end,record.zone())),16,500,NightDialTokens.TEXT);period.setContentDescription("Recorded interval "+RecordUi.date(start,record.zone())+" "+(record.sonar()?RecordUi.preciseClock(this,start,record.zone()):RecordUi.clock(this,start,record.zone()))+" to "+RecordUi.date(end,record.zone())+" "+(record.sonar()?RecordUi.preciseClock(this,end,record.zone()):RecordUi.clock(this,end,record.zone()))+", "+record.zone);Design.space(body,8);Design.text(body,record.sonar()?"Saved echo intervals · missing readings stay blank":"Saved minute averages · missing readings stay blank",12,400,NightDialTokens.SECONDARY);
        String[] names={record.sonar()?"Relative echo change":"Phone movement","Room noise","Room light"},keys={"movement","noise","light"};boolean noise=measured(visible,"noise"),light=measured(visible,"light");int selected=0;for(int n=0;n<keys.length;n++)if(keys[n].equals(metric))selected=n;if(!measured(visible,metric)&&!metric.equals("movement")){metric="movement";selected=0;}Design.space(body,12);metricChoices(body,visible,keys,selected);Design.space(body,12);
        Design.text(body,names[selected],16,500,NightDialTokens.TEXT);chart=new RecordChart(this,visible,metric,start,end,false,record.zone()).measurement(names[selected]);if(inspection>=0)chart.restoreInspection(inspection);body.addView(chart,new LinearLayout.LayoutParams(-1,Design.dp(this,224)));Design.space(body,8);Design.text(body,metric.equals("light")?"Lux from this phone’s light sensor.":metric.equals("noise")?"Relative sound level · not calibrated decibels.":record.sonar()?"Relative echo change. Unavailable and paused intervals remain blank.":"Relative movement from your phone. Heights use this period’s recorded maximum.",13,400,NightDialTokens.SECONDARY);Design.space(body,12);Design.text(body,"Source · "+(record.sonar()?"Contactless sonar capture":"Phone sensors")+" · "+RecordUi.date(end,record.zone()),12,400,NightDialTokens.SECONDARY);
        if(record.sonar()){quality(body,visible,start,end);destination(body,"wave","Breathing rhythm","Recorded periodic echoes",()->startActivity(RecordUi.intent(this,EchoPeriodsActivity.class).putExtra("record",record.id)));}else if(!measured(visible,"movement"))Design.text(body,"No phone movement measurements in this period.",14,400,Design.MUTED);
        if(!noise&&!light){Design.space(body,16);Design.text(body,savedClips>0?"No sound-level or light readings saved.":"No sound-level, light readings or audio clips saved.",12,400,Design.MUTED);}
        boolean analysis=false;for(JSONObject event:events){long time=event.optLong("time"),duration=Math.max(0,event.optLong("duration_ms"));if(time<end&&time+duration>start){analysis=true;break;}}SoundAnalysisCopy.Info sound=SoundAnalysisCopy.of(record);RecordUi.heading(body,"Sound analysis");Design.text(body,sound.title,14,500,sound.attention?Design.BROWN:Design.MUTED);if(!sound.detail.isEmpty())Design.text(body,(record.edited?"Original recording · ":"")+sound.detail,12,400,Design.MUTED);if(analysis||!record.soundAnalysis.isEmpty())destination(body,"wave","Sound events","Estimates and recordings",()->startActivity(RecordUi.intent(this,SoundEventsActivity.class).putExtra("record",record.id)));
        if(!record.sonar()&&record.source.equals("tracked"))destination(body,"link","Paired movement","Separate peer readings and quality",()->startActivity(RecordUi.intent(this,PairMotionSavedActivity.class).putExtra("record",record.id)));
        destination(body,"moon","Timed dream cues","Saved requests for this night",()->startActivity(RecordUi.intent(this,DreamCueHistoryActivity.class).putExtra("record",record.id)));
        if(savedClips>0)destination(body,"sound","Review sound recordings",savedClips+" saved",()->startActivity(RecordUi.intent(this,SoundEventsActivity.class).putExtra("record",record.id)));else if(noise||light){Design.space(body,8);Design.text(body,"No audio clips saved.",12,400,Design.MUTED);}if(!record.edit.note.isBlank()){RecordUi.heading(body,"Notes");Design.text(body,record.edit.note,14,400,Design.INK);}if(!record.edit.tags.isEmpty()){RecordUi.heading(body,"Tags");Design.text(body,record.edit.tags.stream().map(tag->TagCodec.display(record.edit,tag)).collect(java.util.stream.Collectors.joining(" · ")),14,400,Design.MUTED);destination(body,"tag","Compare & manage tags","Saved record associations",()->startActivity(RecordUi.intent(this,TagManagementActivity.class).putExtra("tag",record.edit.tags.get(0))));}destination(body,"memory","Dream diary","Private journal entries",()->startActivity(RecordUi.intent(this,DiaryActivity.class)));Design.space(body,16);
    }
    private void destination(LinearLayout body,String icon,String title,String subtitle,Runnable action){LinearLayout row=PlanActivity.detail(body,icon,title,subtitle,null,action);row.setFocusable(true);SoundEventUi.button(row);}
    private void rememberInspection(){if(chart!=null&&chart.inspectedTime()!=null)inspection=chart.inspectedTime();}
    private void metricChoices(LinearLayout body,List<JSONObject> rows,String[] keys,int selected){LinearLayout rail=Design.row(this);rail.setBackground(Design.shape(this,NightDialTokens.SURFACE,14));String[] labels={"Movement","Noise","Light"};for(int n=0;n<keys.length;n++){String key=keys[n];boolean available=measured(rows,key)||key.equals("movement")&&record.sonar();boolean active=n==selected;FrameLayout hit=new FrameLayout(this);TextView label=Design.text(this,labels[n],13,active?600:400,active?NightDialTokens.ACTION_INK:available?NightDialTokens.SECONDARY:NightDialTokens.META);label.setGravity(Gravity.CENTER);if(active)label.setBackground(Design.shape(this,NightDialTokens.ACCENT,12));FrameLayout.LayoutParams face=new FrameLayout.LayoutParams(-1,Design.dp(this,36),Gravity.CENTER);face.setMargins(Design.dp(this,3),0,Design.dp(this,3),0);hit.addView(label,face);hit.setSelected(active);hit.setFocusable(true);SleepPicker.radio(hit,active);hit.setContentDescription(labels[n]+(available?" signal":" signal unavailable; no saved measurements"));hit.setEnabled(available);hit.setOnClickListener(v->{if(active)return;rememberInspection();InteractionFeedback.selection(v);metric=key;render();});rail.addView(hit,new LinearLayout.LayoutParams(0,Design.dp(this,48),1));}body.addView(rail);}
    private static boolean measured(List<JSONObject> rows,String key){for(JSONObject row:rows){if(row.isNull(key))continue;double value=row.optDouble(key,Double.NaN);if(Double.isFinite(value)&&value>=0)return true;}return false;}
    private void quality(LinearLayout body,List<JSONObject> visible,long start,long end){
        RecordUi.heading(body,"Signal quality");Map<String,Long> totals=new LinkedHashMap<>();long coveredUntil=start,missing=0;for(JSONObject row:visible){long from=Math.max(start,row.optLong("start")),to=Math.min(end,row.optLong("time"));if(to<=from)continue;if(from>coveredUntil)missing+=from-coveredUntil;long uniqueFrom=Math.max(from,coveredUntil);if(to>uniqueFrom){String state=row.optString("signal_quality","UNAVAILABLE");totals.merge(state,to-uniqueFrom,Long::sum);coveredUntil=to;}}if(coveredUntil<end)missing+=end-coveredUntil;
        for(Map.Entry<String,Long> entry:totals.entrySet())qualityRow(body,qualityName(entry.getKey()),entry.getValue());if(missing>0)qualityRow(body,"Not recorded",missing);if(totals.isEmpty()&&missing==0)Design.text(body,"No quality intervals saved.",14,400,Design.MUTED);Design.space(body,8);Design.text(body,"Unavailable intervals stay blank. Zero is a measured value.",12,400,Design.MUTED);
    }
    private void qualityRow(LinearLayout body,String state,long duration){LinearLayout row=Design.row(this);Design.pad(row,0,7);row.addView(Design.text(this,state,14,500,Design.INK),new LinearLayout.LayoutParams(0,-2,1));row.addView(Design.text(this,RecordUi.duration(duration),14,400,Design.MUTED));row.setContentDescription(state+" · "+RecordUi.duration(duration));body.addView(row,new LinearLayout.LayoutParams(-1,-2));}
    private static String qualityName(String state){return switch(state){case "VALID"->"Measured";case "CALIBRATING"->"Calibrating";case "NEEDS_MOVEMENT"->"Awaiting movement";case "NO_ECHO"->"No echo";case "CLIPPED"->"Signal clipped";case "TIMING_LOST"->"Timing lost";case "ROUTE_LOST"->"Audio route lost";case "SILENCED"->"Input silenced";case "CHARGING_LOST"->"Charging stopped";case "CUE_ACTIVE"->"Vibration cue settling";default->"Unavailable";};}
    @Override protected void onSaveInstanceState(Bundle state){rememberInspection();state.putString("metric",metric);state.putLong("inspection",inspection);state.putBoolean("original",original);super.onSaveInstanceState(state);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    void awaitReaders(long timeoutMillis)throws Exception{if(worker.isShutdown()){if(!worker.awaitTermination(timeoutMillis,TimeUnit.MILLISECONDS))throw new TimeoutException("Signal reader still active");}else worker.submit(()->{}).get(timeoutMillis,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
}
